<?php require_once '../includes/config.php'; require_role('admin'); $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$st=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$st->execute([$_POST['status'],(int)$_POST['id']]);flash('success','Order status updated.');redirect('orders.php');}$orders=$pdo->query('SELECT o.*,u.name customer FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC')->fetchAll();$title='Admin Orders';require '../includes/header.php'; ?><h1 class="section-title">Orders</h1><div class="bg-white border rounded-4 overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>#</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?= $o['id'] ?></td><td><?= e($o['customer']) ?></td><td>₹<?= number_format($o['total'],2) ?></td><td><?= e($o['payment_method']) ?></td><td><?= e($o['status']) ?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="id" value="<?= $o['id'] ?>"><select name="status" class="form-select form-select-sm"><option>placed</option><option>confirmed</option><option>processing</option><option>shipped</option><option>out for delivery</option><option>delivered</option><option>cancelled</option></select><button class="btn btn-sm btn-purple">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><?php require '../includes/footer.php'; ?>
